input.script:
export const meta = {
  name: 'file-words',
  description: 'Read README.md and list files, answer each in one word, then sum up in one sentence',
  phases: [
    { title: 'Read', detail: 'two agents: one reads README.md, one lists files with ls' },
    { title: 'Sum up', detail: 'one agent joins the two one-word answers into one sentence' },
  ],
}

phase('Read')
const [readme, listing] = await parallel([
  () => agent('Read the file README.md in the current working directory. Answer with exactly one word describing it. Reply with only that word, no punctuation or other text.', {label: 'read README.md', phase: 'Read'}),
  () => agent('Run `ls` in the current working directory and look at the file names. Answer with exactly one word describing the listing. Reply with only that word, no punctuation or other text.', {label: 'ls files', phase: 'Read'}),
])

phase('Sum up')
const sentence = await agent(
  `Two one-word answers were given about a project directory. The README.md answer was "${readme}". The file listing answer was "${listing}". Join them into exactly one sentence. Reply with only that sentence.`,
  {label: 'sum up', phase: 'Sum up'}
)

return sentence

